// encode_cyclic takes a vector `s` of i8’s, and returns a new vector
// of the same length in which every full block of 3 elements
// is cyclically rotated left by one position (0→2, 1→0, 2→1),
// and any leftover (0, 1, or 2) elements at the end are copied unchanged.

#[requires(true)]
#[ensures(
    |ret: Vec<i8>| {
        // 1. Length is preserved
        ret.len() == s.len()
        // 2. For each index i < ret.len(), either:
        //    - i lies in a full 3-block, and ret[i] is the
        //      (i%3+1)%3 element of that block in s, or
        //    - i lies in the remainder, and ret[i] == s[i].
        && forall(|i: usize| (i < ret.len()) ==>
            if i < (s.len() / 3) * 3 {
                // i is in a full block
                let block_start = (i / 3) * 3;
                let in_block = i % 3;
                ret[i] == s[block_start + ((in_block + 1) % 3)]
            } else {
                // i is in the leftover remainder
                ret[i] == s[i]
            }
        )
    }
)]
fn encode_cyclic(s: Vec<i8>) -> Vec<i8> {
    let mut res = Vec::with_capacity(s.len());
    let mut chunks = s.chunks_exact(3);

    // Process each complete block of 3 elements
    for chunk in chunks.by_ref() {
        // chunk[0] -> goes to position 2
        // chunk[1] -> goes to position 0
        // chunk[2] -> goes to position 1
        res.push(chunk[1]);
        res.push(chunk[2]);
        res.push(chunk[0]);
    }

    // Append any leftover elements (0, 1, or 2 of them) unchanged
    res.extend_from_slice(chunks.remainder());
    res
}

